using APX.Domain.Catalog;
namespace APX.Domain.Requests;
public enum ProjectRequestStatus { New, Contacted, Qualified, Closed, Archived }
public sealed class ProjectRequest { public Guid Id { get; set; } public string Name { get; set; } = string.Empty; public string Company { get; set; } = string.Empty; public string Email { get; set; } = string.Empty; public string Phone { get; set; } = string.Empty; public string ProjectType { get; set; } = string.Empty; public string City { get; set; } = string.Empty; public DateOnly? ApproximateDate { get; set; } public int? Attendees { get; set; } public string? Message { get; set; } public ProjectRequestStatus Status { get; set; } = ProjectRequestStatus.New; public string Source { get; set; } = "web"; public DateTimeOffset CreatedAt { get; set; } public DateTimeOffset UpdatedAt { get; set; } public ICollection<ProjectRequestItem> Items { get; } = new List<ProjectRequestItem>(); }
public sealed class ProjectRequestItem { public Guid Id { get; set; } public Guid ProjectRequestId { get; set; } public ProjectRequest ProjectRequest { get; set; } = null!; public Guid SolutionId { get; set; } public Solution Solution { get; set; } = null!; public int Quantity { get; set; } = 1; public DateTimeOffset AddedAt { get; set; } public string SolutionNameSnapshot { get; set; } = string.Empty; public string? Notes { get; set; } }
